```
struct data {
 int sum, pref, suff, ans;
};

data combine(data l, data r) {
 data res;
 res.sum = l.sum + r.sum;
 res.pref = max(l.pref, l.sum + r.pref);
 res.suff = max(r.suff, r.sum + l.suff);
 res.ans = max(max(l.ans, r.ans), l.suff + r.pref);
 return res;
}

