void rollback() {  if (op.empty())  return;  dsu_save x = op.top();  op.pop();  comps++;  p[x.v] = x.v;  rnk[x.v] = x.rnkv;  p[x.u] = x.u;  rnk[x.u] = x.rnku;  } };

