Following is an implementation of Gauss-Jordan. Choosing the pivot row is done with heuristic: choosing maximum value in the current column. The input to the function gauss is the system matrix $a$ . The last column of this matrix is vector $b$ . The function returns the number of solutions of the system $(0, 1,\textrm{or } \infty)$ . If at least one solution exists, then it is returned in the vector $ans$ . ``` const double EPS = 1e-9; const int INF = 2; // it doesn't actually have to be infinity or a big number

int n = (int) a.size();  int m = (int) a[0].size() - 1;

for (int col=0, row=0; col<m && row<n; ++col) {  int sel = row;  for (int i=row; i<n; ++i)

sel = i;  if (abs (a[sel][col]) < EPS)  continue;  for (int i=col; i<=m; ++i)  swap (a[sel][i], a[row][i]);  where[col] = row;

for (int i=0; i<n; ++i)  if (i != row) {  double c = a[i][col] / a[row][col];  for (int j=col; j<=m; ++j)  a[i][j] -= a[row][j] * c;  }  ++row;  }

