``` public static BigInteger isqrtNewton(BigInteger n) {  BigInteger a = BigInteger.ONE.shiftLeft(n.bitLength() / 2);  boolean p_dec = false;  for (;;) {  BigInteger b = n.divide(a).add(a).shiftRight(1);  if (a.compareTo(b) == 0 || a.compareTo(b) < 0 && p_dec)  break;

a = b;  }  return a; }

