/* I < 0 if z inside C,

I = 0 if z on the circumference of C */ ftype indicator(mec const& C, point z) {  return visit([&](auto &&C) {  point a = C[0], b = C[1];  point I0 = (b - z) * conj(a - z);  if constexpr (size(C) == 2) {  return real(I0);  } else {  point c = C[2];  point I2 = (a - c) * conj(b - c);  point I1 = I0 * I2;  return imag(I2) < 0 ? -imag(I1) : imag(I1);  }  }, C); }

bool inside(mec const& C, point p) {  return indicator(C, p) <= 0; }

