Now we can implement the entire algorithm. First we construct the graph of implications and find all strongly connected components. This can be accomplished with Kosaraju's algorithm in $O(n + m)$ time. In the second traversal of the graph Kosaraju's algorithm visits the strongly connected components in topological order, therefore it is easy to compute $\text{comp}[v]$ for each vertex $v$ . Afterwards we can choose the assignment of $x$ by comparing $\text{comp}[x]$ and $\text{comp}[\lnot x]$ . If $\text{comp}[x] = \text{comp}[\lnot x]$ we return $\text{false}$ to indicate that there doesn't exist a valid assignment that satisfies the 2-SAT problem. Below is the implementation of the solution of the 2-SAT problem for the already constructed graph of implication $adj$ and the transpose graph $adj^{\intercal}$ (in which the direction of each edge is reversed). In the graph the vertices with indices $2k$ and $2k+1$ are the two vertices corresponding to variable $k$ with $2k+1$ corresponding to the negated variable. ``` struct TwoSatSolver {  int n_vars;  int n_vertices;

TwoSatSolver(int _n_vars) : n_vars(_n_vars), n_vertices(2 * n_vars), adj(n_vertices), adj_t(n_vertices), used(n_vertices), order(), comp(n_vertices, -1), assignment(n_vars) {  order.reserve(n_vertices);  }  void dfs1(int v) {  used[v] = true;  for (int u : adj[v]) {  if (!used[u])  dfs1(u);  }  order.push_back(v);  }

void dfs2(int v, int cl) {  comp[v] = cl;  for (int u : adj_t[v]) {  if (comp[u] == -1)  dfs2(u, cl);  }  }

bool solve_2SAT() {  order.clear();  used.assign(n_vertices, false);  for (int i = 0; i < n_vertices; ++i) {  if (!used[i])  dfs1(i);  }

comp.assign(n_vertices, -1);  for (int i = 0, j = 0; i < n_vertices; ++i) {  int v = order[n_vertices - i - 1];  if (comp[v] == -1)  dfs2(v, j++);  }

assignment.assign(n_vars, false);  for (int i = 0; i < n_vertices; i += 2) {  if (comp[i] == comp[i + 1])  return false;

}  return true;  }

void add_disjunction(int a, bool na, int b, bool nb) {  // na and nb signify whether a and b are to be negated

a = 2 * a ^ na;  b = 2 * b ^ nb;  int neg_a = a ^ 1;  int neg_b = b ^ 1;  adj[neg_a].push_back(b);  adj[neg_b].push_back(a);  adj_t[b].push_back(neg_a);  adj_t[a].push_back(neg_b);  }

static void example_usage() {  TwoSatSolver solver(3); // a, b, c  solver.add_disjunction(0, false, 1, true); // a v not b  solver.add_disjunction(0, true, 1, true); // not a v not b  solver.add_disjunction(1, false, 2, false); // b v c  solver.add_disjunction(0, false, 0, false); // a v a  assert(solver.solve_2SAT() == true);

assert(solver.assignment == expected);  } };

