constexpr int MAX_N = 4e5 + 5; constexpr int LG = 20;

int n, m, q, va[MAX_N], f[MAX_N], nx; int trace(int v) { return f[v] == v ? v : f[v] = trace(f[v]); }

/** Implements LCA with binary lifting */ namespace LCA { int lift[MAX_N][LG], ch[MAX_N][2], t, tin[MAX_N], tout[MAX_N], tour[2 * MAX_N];

int lca(int u, int v) { 	if (is_ancestor(u, v)) { return u; } 	if (is_ancestor(v, u)) { return v; }

if (!is_ancestor(lift[u][i], v)) { u = lift[u][i]; } 	}

