void dfs(int v) { 	if (v == -1) { return; } 	tour[t] = v; 	tin[v] = t;

for (int i = 1; i < LG; i++) { lift[v][i] = lift[lift[v][i - 1]][i - 1]; }

dfs(ch[v][0]); 	dfs(ch[v][1]); 	tout[v] = t++; } }  // namespace LCA

/** Point Update / Range Min/Max Segment Tree */ namespace SGT { int sg_min[1 << LG + 1], sg_max[1 << LG + 1];

void point_set(int i, int v) { 	sg_min[i + (1 << LG)] = sg_max[i + (1 << LG)] = v; 	for (int j = (i + (1 << LG)) / 2; j; j /= 2) {

sg_min[j] = min(sg_min[2 * j], sg_min[2 * j + 1]),

sg_max[j] = max(sg_max[2 * j], sg_max[2 * j + 1]); 	} }

/** @return edge (LCA of nodes w/ lowest and highest traversal time in [l, r]) */ int query(int l, int r) { 	int lift = MAX_N, rt = -1;

if (l & 1) { lift = min(lift, sg_min[l]), rt = max(rt, sg_max[l++]); }

if (r & 1) { lift = min(lift, sg_min[--r]), rt = max(rt, sg_max[r]); } 	} 	return va[LCA::lca(LCA::tour[lift], LCA::tour[rt])]; } }  // namespace SGT

void solve() {

iota(f, f + 2 * n, 0); 	nx = n; 	memset(LCA::ch, -1, sizeof(LCA::ch));

