By supporting path queries with HLD, we can solve this problem in $\mathcal{O}(S\cdot(n + m\log^2n))$. ```cpp #include "bits/stdc++.h" using namespace std;

using us = unsigned short;

const int MAX_N = 5e5 + 1; const int S = 150; const us INF = 65535;

us va[MAX_N][S]; int n, m, c[MAX_N];

namespace SGT { const int L = 1 << 19; us seg[2 * L][S];

void build() { 	for (int i = L - 1; i; i--) {

for (int j = 0; j < S; j++) {

seg[i][j] = min(seg[2 * i][j], seg[2 * i + 1][j]);

} 	} }

void point_update(int idx, int v) { 	int pos = L + idx; 	for (int j = 0; j < S; j++) { seg[pos][j] = va[v][j]; } 	pos /= 2; 	while (pos) {

int left = pos * 2, right = left + 1;

for (int j = 0; j < S; j++) { seg[pos][j] = min(seg[left][j], seg[right][j]); }

pos /= 2; 	} }

inline us range_min(int l, int r, int j) { 	us res = INF; 	for (l += L, r += L + 1; l < r; l /= 2, r /= 2) {

if (l & 1) res = min(res, seg[l++][j]);

if (r & 1) res = min(res, seg[--r][j]); 	} 	return res; } }  // namespace SGT

namespace HLD { const int MAX_N = 5e5 + 1; int f[MAX_N], depth[MAX_N], heavy[MAX_N], head[MAX_N], pos[MAX_N], cp = 0;

void clear(int n) { 	for (int i = 0; i < n; i++) { adj[i].clear(); } 	cp = 0; }

void add_edge(int u, int v) { 	adj[u].push_back(v); 	adj[v].push_back(u); }

int dfs(int v) { 	int sz = 1, msz = 0; 	for (int nxt : adj[v]) {

if (nxt != f[v]) {

f[nxt] = v;

depth[nxt] = depth[v] + 1;

int csz = dfs(nxt);

sz += csz;

msz = csz;

heavy[v] = nxt;

}

} 	}

return sz; }

void decompose(int v, int h) { 	head[v] = h; 	pos[v] = cp++; 	for (int j = 0; j < S; j++) SGT::seg[SGT::L + pos[v]][j] = va[c[v]][j]; 	if (heavy[v] != -1) decompose(heavy[v], h); 	for (int nxt : adj[v]) {

if (nxt == f[v] || nxt == heavy[v]) continue;

decompose(nxt, nxt); 	} }

inline void init() { 	memset(heavy, -1, sizeof(heavy)); 	dfs(0); 	decompose(0, 0); }

us path_min(int a, int b, int j) { 	us res = INF; 	while (head[a] != head[b]) {

res = min(res, SGT::range_min(pos[head[b]], pos[b], j));

b = f[head[b]]; 	}

res = min(res, SGT::range_min(pos[a], pos[b], j)); 	return res; } }  // namespace HLD

void solve() {

HLD::clear(n); 	for (int i = 1; i < n; i++) {

int u, v;

u--, v--;

HLD::add_edge(u, v); 	}

HLD::init(); 	SGT::build();

