int tp;

if (tp == 1) {

int x, y;

x ^= cnt;

y ^= cnt;

SGT::point_update(HLD::pos[x - 1], y);

} else {

int a, b, cc, d;

a ^= cnt, b ^= cnt, cc ^= cnt, d ^= cnt;

a--, b--, cc--, d--;

long long c1 = 0, c2 = 0;

for (int j = 0; j < S; j++) {

c1 += HLD::path_min(a, b, j);

c2 += HLD::path_min(cc, d, j);

